// Fichiers en conflit potentiel avant une fusion.
export function conflictingFiles(oursChanged, theirsChanged) {
  // BUG : renvoie tout ce qui a changé d'un côté OU de l'autre (union), pas l'intersection.
  return [...new Set([...oursChanged, ...theirsChanged])].sort();
}

